std::vector<Adhesion::Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    Weighted_point wp = vit->point();
    RT::Cell_handle c = vit->cell();

    Adhesion::Node node;
    node.position = {wp.x(), wp.y(), wp.z()};
    node.velocity = velocity(c);
    node.mass = wp.weight();
    node.node_type = type_from_edge_count(edge_count(c, threshold));

    nodes.push_back(node);
}

return nodes;

